package com.dentalclinic.patientcare.exception;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.util.*;@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(ResourceNotFoundException.class)ResponseEntity<?> nf(ResourceNotFoundException e){return ResponseEntity.status(404).body(Map.of("message",e.getMessage()));}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<?> val(MethodArgumentNotValidException e){Map<String,String> m=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->m.put(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(Map.of("message","Validation failed","errors",m));}@ExceptionHandler(Exception.class)ResponseEntity<?> ex(Exception e){return ResponseEntity.status(500).body(Map.of("message",e.getMessage()==null?"Server error":e.getMessage()));}}